/**
 * BETA OFFICE experiment — Lights Out
 * Click toggles a cell and its orthogonal neighbors; the goal is all
 * lights off. Every puzzle is generated by scrambling from the solved
 * state, so it's always solvable.
 */
(function () {
  if (!window.BetaExperiments) return;

  var SIZE = 5;
  var SCRAMBLE_MOVES = 12;

  window.BetaExperiments.registerExperiment({
    id: "lightsout",
    name: "Lights Out",
    category: "LIGHTSOUT",
    description: "Click toggles a cell + neighbors, turn them all off",
    launch: function (container) {
      var grid = document.createElement("div");
      grid.className = "beta-lightsout-grid";
      container.appendChild(grid);

      var readout = window.BetaControls.readout(container);
      var cells = [];
      var state = { lights: null, moves: 0, over: false };

      function idx(x, y) { return y * SIZE + x; }

      function toggle(i, silent) {
        var x = i % SIZE;
        var y = (i / SIZE) | 0;
        [[0, 0], [1, 0], [-1, 0], [0, 1], [0, -1]].forEach(function (d) {
          var nx = x + d[0];
          var ny = y + d[1];
          if (nx >= 0 && nx < SIZE && ny >= 0 && ny < SIZE) {
            var n = idx(nx, ny);
            state.lights[n] = !state.lights[n];
          }
        });
        if (!silent) render();
      }

      function render() {
        cells.forEach(function (c, i) { c.classList.toggle("beta-is-on", state.lights[i]); });
        if (!state.over && state.lights.every(function (v) { return !v; })) state.over = true;
        readout.innerHTML = state.over
          ? "<strong>Solved</strong> in " + state.moves + " moves"
          : "Moves: <strong>" + state.moves + "</strong>";
      }

      function onClick(i) {
        if (state.over) return;
        state.moves++;
        toggle(i);
      }

      function build() {
        state.lights = new Array(SIZE * SIZE).fill(false);
        state.moves = 0;
        state.over = false;
        for (var k = 0; k < SCRAMBLE_MOVES; k++) toggle((Math.random() * SIZE * SIZE) | 0, true);
        render();
      }
      // Exposed so reset() (registered outside this closure) can scramble
      // a fresh puzzle without reaching into loose local variables.
      state.restart = build;

      for (var i = 0; i < SIZE * SIZE; i++) {
        var cell = document.createElement("button");
        cell.type = "button";
        cell.className = "beta-lightsout-cell";
        (function (cellIdx) {
          cell.addEventListener("click", function () { onClick(cellIdx); });
        })(i);
        grid.appendChild(cell);
        cells.push(cell);
      }

      window.BetaControls.miniBtn(container, "New puzzle", build);
      build();

      container._betaState = state;
      return function cleanup() {};
    },
    reset: function (container) {
      var s = container._betaState;
      if (!s) return;
      s.restart();
    },
  });
})();
